import React from "react";

export default function Allservices() {
  const services = [
    {
      title: "Live Stream",
      description:
        "Go live instantly and connect with your audience in real-time. Enjoy smooth, high-quality video streaming with minimal delays, and engage with your viewers through authentic, interactive moments that help you grow your fan base and create a loyal, supportive community.",
      image: "/images/live-stream.jpg",
    },
    {
      title: "Multi Video Stream",
      description:
        "Stream from multiple sources at once, giving your audience the freedom to choose how they watch. Whether it’s different camera angles, separate events, or backstage access, multi-stream keeps viewers entertained, engaged, and connected to the action from every perspective.",
      image: "/images/multi-stream.jpg",
    },
    {
      title: "Live Chat Room",
      description:
        "Boost engagement with our interactive live chat rooms. Viewers can send messages, emojis, and reactions in real time while watching your stream, creating an exciting, social, and inclusive experience that makes your audience feel involved and part of the action every second.",
      image: "/images/live-chat.jpg",
    },
    {
      title: "Family Channels",
      description:
        "Create private or public family channels where members can stream, share, and enjoy content together. Perfect for friends, teams, and communities, these channels make it easy to stay connected, host group events, and share your moments with those who matter most to you.",
      image: "/images/family-channels.jpg",
    },
    {
      title: "Easy & Fast Withdrawals",
      description:
        "Get your earnings quickly and securely with our simple withdrawal process. No unnecessary delays or hidden steps—just fast, reliable payouts that let you focus on your content while we handle the transactions, ensuring you always get paid for your hard work without stress.",
      image: "/images/withdrawals.jpg",
    },
    {
      title: "Profile & Post System",
      description:
        "Showcase your personality, achievements, and content with a customizable profile page. Share posts, photos, and updates to keep your audience engaged, build your personal brand, and grow your streaming presence both during live events and in-between your broadcasts.",
      image: "/images/profile-post.jpg",
    },
  ];

  return (
    <div className="bg-gradient-to-b from-[#0a0a0f] to-[#111] py-20">
      <div className="max-w-6xl mx-auto px-4 space-y-24">
        {services.map((service, index) => (
          <div
            key={index}
            className={`flex flex-col md:flex-row items-center gap-12 ${
              index % 2 !== 0 ? "md:flex-row-reverse" : ""
            }`}
          >
            {/* Image Section with Tilt */}
            <div className="md:w-1/2 relative group perspective">
              <div className="relative transform transition-transform duration-500 group-hover:rotate-2 group-hover:scale-105 rounded-2xl overflow-hidden shadow-lg shadow-[#8944F5]/40">
                <img
                  src={service.image}
                  alt={service.title}
                  className="w-full h-[350px] object-cover"
                />
                <div className="absolute inset-0 bg-[#8944F5]/30 opacity-0 group-hover:opacity-100 transition duration-700 ease-out"></div>
              </div>
            </div>

            {/* Text Section */}
            <div className="md:w-1/2 space-y-6 text-center md:text-left">
              <h2 className="text-3xl md:text-4xl font-bold text-white leading-tight">
                {service.title}
              </h2>
              <p className="text-lg text-gray-300 leading-relaxed">
                {service.description}
              </p>
              <button className="px-8 py-3 bg-[#8944F5] hover:bg-[#7838d8] text-white font-medium rounded-xl shadow-[0_0_15px_rgba(137,68,245,0.7)] hover:shadow-[0_0_30px_rgba(137,68,245,1)] transform hover:scale-105 transition duration-500 ease-out">
                Learn More
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
